UPDATE companies SET description='Tundra Apparel & Promotions was founded in 2006 in Green Bay, Wisconsin. The company operates from a facility on Ashwaubenon Street and serves customers across Northeastern Wisconsin and beyond.

The shop provides custom decoration services including screen printing, embroidery, applique, heat press, and general customization. An in-house design team prepares artwork for production, and all work is performed on-site by a print crew with more than 20 years of combined experience. The company handles order quantities ranging from single pieces to runs of 1,000 or more, with a standard turnaround of 7 to 10 business days and quotes delivered within 24 hours.

Clients include event organizers such as Gus Macker, corporate accounts like Red Hat, and design firms such as White Design House. The business focuses on decorated apparel and promotional products for a variety of promotional and branding needs.

Tundra emphasizes that every item moves through the full production process in its own facility, eliminating middleman markups. Each piece is inspected before delivery, and the company positions its pricing as competitive because it controls the entire workflow from design to finished goods.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Screen Printing", "Embroidery", "Applique", "Heat Press", "Customization", "Graphic Design"], "industries": [], "materials": ["Garments", "Promotional products"], "equipment": [], "volume": "1 to 1000+ units", "lead_time": "7-10 business days", "tolerances": "", "built_on": ["In-house design team prepares files for production", "All decoration performed on-site with no middleman", "Print crew with over 20 years of experience", "Quotes provided within 24 hours", "Standard turnaround of 7\u201310 business days"], "facts_used": ["Founded in 2006 -> db", "Headquarters Green Bay, Wisconsin -> db", "Address 1164 Ashwaubenon St Green Bay, WI 54304 -> /", "Services: Screen Printing, Embroidery, Applique, Heat Press, Customization -> /", "In-house design team -> /", "Print crew with over 20 years experience -> /", "All production on-site, no middleman -> /", "Turnaround 7-10 business days -> /", "Quote within 24 hours -> /", "Quantity ranges 1-50 to 1000+ -> /", "Clients: Gus Macker, Red Hat, White Design House -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Services We Provide: Screen Printing, Embroidery, Applique, Heat Press, Customization", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tundra-apparel-promotions' AND approved AND profile IS NULL;
UPDATE companies SET description='Tungsten Parts Wyoming (TPW) is a U.S.-owned tungsten manufacturer based in Laramie, Wyoming, led by CEO Mark Holden. The company operates two production facilities in Laramie, producing high-density tungsten components from powder to finish.

TPW produces tungsten products and custom tungsten components using powder-to-finish processes that include precision finishing, production execution, and first-article inspection. The facilities span 50,000 square feet with 24/7 production capability and an annual capacity of 1.6 million kilograms.

The company serves defense, aerospace, and industrial customers who require dependable supply, repeatable manufacturing outcomes, and parts that meet exact specifications. Engineers and procurement teams rely on TPW for consistent density, predictable delivery, and documentation that withstands program review.

TPW differentiates itself by controlling the full process from powder to finished part, offering cobalt-free chemistry when required, and maintaining compliance with ISO 9001, AS9100D, ITAR, DFARS, and CAGE 842W5. Domestic powder-to-finish production reduces supply-chain risk and provides direct accountability.', certifications=ARRAY['ISO 9001','AS9100D','ITAR','DFARS','CAGE 842W5']::text[], profile='{"capabilities": ["Powder metallurgy", "Sintering", "Precision machining", "First-article inspection", "Controlled production documentation", "Custom tungsten component manufacturing", "Powder-to-finish production"], "industries": ["Defense", "Aerospace", "Industrial"], "materials": ["Tungsten", "Cobalt-free tungsten alloys"], "equipment": [], "volume": "Up to 1.6 million kg annually", "lead_time": "", "tolerances": "", "built_on": ["Powder-to-finish production in Laramie, Wyoming", "Two U.S. production facilities ensuring resilient domestic supply", "ISO 9001, AS9100D, ITAR, and DFARS compliance with CAGE 842W5", "Cobalt-free chemistry available", "24/7 production capability with 1.6 million kg annual capacity"], "facts_used": ["Location: Laramie, Wyoming -> /about", "CEO: Mark Holden -> /about", "Two production facilities in Laramie -> /about", "50,000 square feet facility size -> /", "24/7 production capability -> /", "Annual capacity 1.6 million kg -> /", "Powder-to-finish production -> /about", "ISO 9001 certified -> /about, db", "AS9100D certified -> db (description)", "ITAR registered -> /about, db", "DFARS capable -> /about", "CAGE code 842W5 -> /about", "Cobalt-free chemistry available -> /about", "Industries: Defense, Aerospace, Industrial -> /, /about", "Custom tungsten components -> /about", "First-article inspection -> /about", "Controlled production documentation -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Tungsten Parts Wyoming (TPW) is a U.S. owned and operated tungsten manufacturer based in Laramie, Wyoming", "founded_year": "", "employee_count": "", "cage_code": "842W5", "min_order": "", "export_compliance": ["ITAR registered", "DFARS capable"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tungsten-parts-wyoming' AND approved AND profile IS NULL;
UPDATE companies SET description='Turners Ridge Wood Workz operates from a 2,200-square-foot workshop in La Crosse, Wisconsin. The company was founded in 2019 by David Pehl, who began woodworking as a high‑school hobby in his family garage and later built a backyard shop with his father, Dave.

The shop produces handmade hardwood cutting boards, custom furniture such as kitchen tables, coffee tables, and end tables, and personalized gift items. Each piece is crafted from hand‑selected domestic and exotic hardwoods chosen for color and grain, then finished to a silky smooth surface. The two‑person team handles everything from design and wood selection to final finishing, with typical lead times of two to four weeks for smaller items and six to eight weeks for furniture.

Turners Ridge serves primarily individual consumers seeking one‑of‑a‑kind gifts, wedding presents, family keepsakes, and custom furniture. The company has also donated pieces for community fundraisers, such as a local theater gala. Orders are taken through an online inquiry form, and the showroom is open weekdays for local customers.

The founders emphasize that every item carries a personal touch—“a bit of our heart and craftsmanship”—and they stand behind each piece with a quality guarantee. The business grew from David’s passion for turning raw wood into lasting, functional art, a mission that continues to drive their focus on unique, heirloom‑quality work.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Hardwood cutting board fabrication", "Custom furniture manufacturing", "Custom gift creation", "Wood selection and finishing", "Handmade woodworking"], "industries": [], "materials": ["Domestic hardwoods", "Exotic hardwoods"], "equipment": [], "volume": "", "lead_time": "2\u20134 weeks for standard items; 6\u20138 weeks for furniture", "tolerances": "", "built_on": ["Hand\u2011selected domestic and exotic hardwoods for every project", "Each piece uniquely designed; no two are alike", "Family\u2011run shop with military and law\u2011enforcement background", "Turnaround of 2\u20134 weeks for standard items, 6\u20138 weeks for furniture", "Showroom open Monday\u2013Friday for local pickup and consultation"], "facts_used": ["Founded 2019 -> db", "Headquarters La Crosse, Wisconsin -> db", "Family-owned, small business -> /", "Founders David Pehl and Dave (father) -> /about-us", "2200-square-foot workshop -> /about-us", "Dave retired after 23 years military and 30 years law enforcement -> /about-us", "Hand-selected domestic and exotic hardwoods -> /about-us", "Custom hardwood cutting boards, furniture, gifts -> /services", "Turnaround 2-4 weeks for items, 6-8 weeks for furniture -> /services", "Showroom hours Monday-Friday 9 AM - 5 PM -> /", "Address 1100 Kane Street, Suite 127/128, La Crosse, WI -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Turners Ridge Wood Workz began as a hobby for David, who discovered his passion for woodworking in high school. What started in the family garage quickly grew into a small workshop he built with his dad in the backyard. At just eighteen, David took a bold leap into a 2200-square-foot workshop, turning his dream into a thriving small business.", "founded_year": "2019", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='turners-ridge-wood-workz' AND approved AND profile IS NULL;
UPDATE companies SET description='Tutto Ferro was founded in 2001 by Paolo Cividino in Reno, Nevada. The company began as a fabrication shop focused on high-end metalwork, blending steel with honed concrete, glass, and wood to create architectural elements, custom furniture, and large-scale installations.

The shop operates a state-of-the-art facility equipped with an OMAX waterjet and a high-definition plasma cutter, enabling precision cutting and shaping of metal. Its capabilities span design and engineering—including concept development, prototyping, material selection, and structural analysis—through custom fabrication of stairs, railings, doors, facades, furniture, sculptures, and public art. The team also handles mixed-media integration, combining metal with concrete, glass, and wood, and provides on-site installation services such as assembly, welding, and placement of structural and decorative pieces.

Tutto Ferro serves architects, designers, urban planners, and private clients across the residential, commercial, and public sectors. Its portfolio includes large-scale public art installations throughout Nevada and custom metalwork for high-end homes in the Pacific Northwest. The company works on both public and private commissions, delivering one-of-a-kind pieces for urban environments, commercial spaces, and luxury residences.

