UPDATE companies SET description='Twin Marquis Inc. operates from Brooklyn, New York, where it was founded in 1989. The company began in a small New York factory with the goal of producing fresh, high-quality noodles and wrappers for Chinese consumers in the United States who missed home-cooked flavors.

The company manufactures fresh Asian noodles, wrappers, and frozen dumplings, including fully cooked varieties. Its Brooklyn facility processes 15,000 tons of flour each month, and annual noodle production is said to be enough to circle the Earth 100 times. Twin Marquis also offers custom noodle formulations and private-label manufacturing for wholesale partners.

Products are sold through wholesale channels and Asian supermarkets, serving the Chinese American community and broader markets seeking authentic Asian foods. The company''s customer base includes wholesale distributors and retail grocery chains specializing in Asian cuisine.

Twin Marquis differentiates itself by being the first Asian-food manufacturer in the U.S. to achieve FSSC 22000 certification from NQA. Dozens of its products carry Kosher and Vegan certifications, and all are produced in a USDA-inspected facility. The company emphasizes food safety and the ability to customize products for wholesale clients.', certifications=ARRAY['FSSC 22000','Kosher','Vegan']::text[], profile='{"capabilities": ["Fresh noodle manufacturing", "Wrapper production", "Frozen dumpling manufacturing", "Fully cooked dumpling production", "Custom noodle formulation", "Private label manufacturing", "Wholesale customization", "Food safety certification (FSSC 22000)", "Kosher certification", "Vegan certification", "USDA facility operations"], "industries": ["Asian food manufacturing", "Wholesale food distribution", "Retail (Asian supermarkets)", "Foodservice", "Chinese cuisine"], "materials": ["Wheat flour", "Food ingredients for noodles, wrappers, and dumplings"], "equipment": [], "volume": "15,000 tons of flour per month; annual noodle production circles Earth 100 times", "lead_time": "", "tolerances": "", "built_on": ["First Asian-food manufacturer in the U.S. to obtain FSSC 22000 certification from NQA", "Dozens of products certified Kosher and Vegan", "Manufactured in a USDA-inspected facility", "15,000 tons of flour processed monthly", "Custom noodle and private-label services for wholesale partners"], "facts_used": ["Founded in 1989 -> /about-us", "Headquarters in Brooklyn, New York -> /about-us", "Subsidiary of Schwan''s Shared Services, LLC -> / (copyright)", "Manufactures fresh noodles, wrappers, frozen dumplings -> /about-us", "Processes 15,000 tons of flour monthly -> /about-us", "Annual noodle production circles Earth 100 times -> /about-us", "First Asian-food manufacturer in US with FSSC 22000 certification from NQA -> /about-us", "Products certified Kosher and Vegan -> /about-us", "Manufactured in USDA facility -> /about-us", "Offers custom noodles and private labels -> /about-us", "Serves wholesale partners and Asian supermarkets -> /", "Website available in English and Chinese -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Manufacturer of Fresh Asian Noodles & Wrappers", "founded_year": "1989", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": ["English", "Chinese (Simplified)", "Chinese (Traditional)"], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='twin-marquis-inc' AND approved AND profile IS NULL;
