UPDATE companies SET description='Two Brothers WoodWorks operates from Myrtle Beach, South Carolina. The business began with a focus on creating tables designed to become central gathering places in homes.

The company designs and builds dining and gathering tables using handcrafted woodworking methods. Each piece is assembled in its Myrtle Beach facility with an emphasis on durability and legacy-quality construction.

The company''s stated philosophy, "Don''t Give Up the Craft," reflects a commitment to intentional design and careful construction. It markets its tables as foundations for generational memories, differentiating through a narrative of legacy and American-made craftsmanship rather than technical specifications.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom table design and manufacturing", "Handcrafted woodworking"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Handcrafted construction", "American made", "Built to Last", "Designed with legacy in mind", "Don''t Give Up the Craft philosophy"], "facts_used": ["Location: Myrtle Beach, SC -> db", "Product: Tables (handcrafted, American made) -> /", "Philosophy: ''Don''t Give Up the Craft'' -> /", "Approach: Design and build each table with care, quality, intention -> /", "Target: Residential/family homes -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "When we design and build each table, we do it with one thing in mind \u2014 the life it will live after it leaves our hands.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='two-brothers-woodworks' AND approved AND profile IS NULL;
UPDATE companies SET description='U.S. Pack Group, based in Sunrise, Florida, was founded in 1996 and has built over three decades of experience in PET bottle manufacturing. The company operates a flagship facility in Sunrise and recently inaugurated a new, state-of-the-art plant in Lakeland, Florida, to expand its production capacity and serve clients across the region.

The company creates, develops, and manufactures private-label PET packaging — including Boston Round, Bullet Round, Modern Round, and pharma-specific bottles — along with labeling solutions. Using certified protocols from concept to stock, it offers custom bottle design, inventory planning, forecasting, and warehousing. Both facilities support end-to-end production of containers made entirely in the United States.

U.S. Pack Group serves the personal care, pharmaceutical, household, pet care, and liquor industries. Customers range from brands seeking stock bottle lines to those requiring fully custom packaging developed through the company''s sales and engineering teams.

